// src/lib/decisionTrees.ts
// Decision tree construction (Part 2/3 base capability, extended in Part 4).
//
// Existing exports (preserved): DecisionTreeBranch, DecisionTree,
//   buildDecisionTree.
// New in Part 4: DOMAIN_OPTION_TEMPLATES, DOMAIN_KEY_METRICS,
//   autoGenerateDecisionTree.

import type { Decision, DecisionDomain } from './decisionTypes';
import type { BeliefFabricResult } from './beliefFabric';
import type { ActivatedScenario, MetricKey } from './types';
import { defaultBaselineState, projectScenario } from './scenarioEngine';

export interface LeafOutcome {
  metricKey: MetricKey;
  p50AtMonth6: number;
  degradedOutcome: number;
}

export interface DecisionTreeBranch {
  id: string;
  label: string;
  assumptionSummary: string;
  leafOutcomes: LeafOutcome[];
  probabilityOfDegradation: number;
}

export interface DecisionTree {
  decisionId: string;
  rootLabel: string;
  domain: DecisionDomain;
  branches: DecisionTreeBranch[];
  generatedAt: string;
}

/**
 * buildDecisionTree
 * Baseline (pre-Part-4) tree builder: a simple two-branch "do it / don't"
 * tree with no scenario or belief-fabric awareness. Preserved for callers
 * that only need a structural skeleton.
 */
export function buildDecisionTree(decision: Decision): DecisionTree {
  return {
    decisionId: decision.id,
    rootLabel: decision.title,
    domain: decision.domain,
    branches: decision.options.slice(0, 2).map((label, i) => ({
      id: `${decision.id}_b${i}`,
      label,
      assumptionSummary: 'No scenario modeling applied.',
      leafOutcomes: [],
      probabilityOfDegradation: 0,
    })),
    generatedAt: new Date().toISOString(),
  };
}

/** Two most common decision choices per domain, used when a decision does not define its own options. */
export const DOMAIN_OPTION_TEMPLATES: Record<DecisionDomain, [string, string]> = {
  revenue: ['Discount to retain', 'Hold price and accept attrition'],
  product: ['Ship now', 'Delay for polish'],
  people: ['Hire', 'Hold headcount'],
  capital: ['Raise now', 'Extend runway via cuts'],
  gtm: ['Expand channel', 'Focus the core segment'],
  operations: ['Invest in tooling', 'Maintain status quo'],
};

/** Three metrics most relevant to judging outcomes in each domain. */
export const DOMAIN_KEY_METRICS: Record<DecisionDomain, [MetricKey, MetricKey, MetricKey]> = {
  revenue: ['revenue', 'churnRate', 'grossMargin'],
  product: ['productUsage', 'nps', 'conversionRate'],
  people: ['headcount', 'burnRate', 'productUsage'],
  capital: ['runwayMonths', 'burnRate', 'revenue'],
  gtm: ['pipelineCoverage', 'conversionRate', 'cac'],
  operations: ['grossMargin', 'burnRate', 'productUsage'],
};

function branchOverrides(domain: DecisionDomain, label: string): Partial<Record<MetricKey, number>> {
  const lower = label.toLowerCase();
  const base = defaultBaselineState;
  if (lower.includes('hire')) return { headcount: base.headcount + 2, burnRate: base.burnRate * 1.04 };
  if (lower.includes('hold') || lower.includes('status quo') || lower.includes('maintain')) return {};
  if (lower.includes('discount')) return { revenue: base.revenue * 0.94, churnRate: base.churnRate * 0.8 };
  if (lower.includes('raise')) return { runwayMonths: base.runwayMonths + 9, burnRate: base.burnRate * 1.02 };
  if (lower.includes('cut')) return { burnRate: base.burnRate * 0.82, runwayMonths: base.runwayMonths + 3 };
  if (lower.includes('ship')) return { productUsage: base.productUsage * 1.08, nps: base.nps + 3 };
  if (lower.includes('delay')) return { productUsage: base.productUsage * 0.98 };
  if (lower.includes('expand')) return { pipelineCoverage: base.pipelineCoverage * 1.15, cac: base.cac * 1.1 };
  if (lower.includes('focus')) return { conversionRate: base.conversionRate * 1.06 };
  if (lower.includes('invest')) return { grossMargin: base.grossMargin + 1.5, burnRate: base.burnRate * 1.03 };
  void domain;
  return {};
}

/**
 * autoGenerateDecisionTree
 * Builds a belief-fabric- and scenario-aware decision tree:
 *  - root uses the decision's own options if provided, else the two most
 *    common domain choices from DOMAIN_OPTION_TEMPLATES
 *  - each branch gets a lightweight scenario projection with branch-specific
 *    assumption overrides (hire => +2 headcount, hold => no-op, etc.)
 *  - leaf outcomes report the p50 projection at month 6 for the 3 metrics
 *    most relevant to the decision's domain (DOMAIN_KEY_METRICS)
 *  - a risk overlay applies the belief fabric's cascadeRisk.p as the
 *    probability that either branch's outcome degrades by 20%
 */
export function autoGenerateDecisionTree(
  decision: Decision,
  beliefResult: BeliefFabricResult,
  scenarios: ActivatedScenario[],
): DecisionTree {
  const domain = decision.domain;
  const options: [string, string] =
    decision.options.length >= 2 ? [decision.options[0], decision.options[1]] : DOMAIN_OPTION_TEMPLATES[domain];
  const keyMetrics = DOMAIN_KEY_METRICS[domain];
  const activatedOverrides: Partial<Record<MetricKey, number>> = {};
  for (const s of scenarios) {
    activatedOverrides[s.metricKey] = s.actualValue;
  }
  const baseline = { ...defaultBaselineState, ...activatedOverrides };
  const degradeP = beliefResult.cascadeRisk.p;

  const branches: DecisionTreeBranch[] = options.map((label, i) => {
    const overrides = branchOverrides(domain, label);
    const leafOutcomes: LeafOutcome[] = keyMetrics.map((key) => {
      const projection = projectScenario(baseline, overrides, key, 6, 400);
      const p50AtMonth6 = projection.p50[projection.p50.length - 1] ?? baseline[key];
      return {
        metricKey: key,
        p50AtMonth6,
        degradedOutcome: p50AtMonth6 * 0.8,
      };
    });
    return {
      id: `${decision.id}_b${i}`,
      label,
      assumptionSummary: Object.keys(overrides).length
        ? `Assumes: ${Object.entries(overrides)
            .map(([k, v]) => `${k} → ${Math.round(v as number).toLocaleString()}`)
            .join(', ')}`
        : 'No material change to modeled assumptions.',
      leafOutcomes,
      probabilityOfDegradation: degradeP,
    };
  });

  return {
    decisionId: decision.id,
    rootLabel: decision.title,
    domain,
    branches,
    generatedAt: new Date().toISOString(),
  };
}
